using System.Globalization;
using MaxonSharp.Compiler.Ir.Core;
using MaxonSharp.Compiler.Ir.Dialects;
using MaxonSharp.Compiler.Ir.Passes;

namespace MaxonSharp.Compiler;

/// <summary>
/// Which whole-project walk over a file's top-level typealiases is running. The three are ordered,
/// and the first exists because the other two cannot answer a question about the WHOLE project from
/// inside a per-file loop: a specialization that has to name a generic instance must be able to ask
/// whether the project already names it, and asking the aliases registered so far answers from the
/// order the filesystem handed over the sources.
/// </summary>
public enum TypeAliasScanPhase {
  /// Read every file's declarations into IrModule.DeclaredGenericAliases and register nothing.
  Declarations,
  /// Specialize each declared alias against its source struct. Runs before PreScan, so a source
  /// struct declared in this compilation unit still has no fields — hence Respecialize.
  Specialize,
  /// Re-specialize once PreScan has filled every source struct in, replacing the entries the
  /// Specialize phase froze against an empty struct.
  Respecialize,
}

public class Parser(List<Token> tokens, IrModule<MaxonOp>? seedModule = null, bool isStdlib = false, string? sourceFilePath = null, string targetOs = "Windows", string targetArch = "x64", bool testing = false, string? rootPath = null, Dictionary<string, object>? foreignPerspectiveCache = null, IReadOnlySet<string>? compilerOwnedDeclarations = null) {
  private List<Token> _tokens = tokens;
  private readonly bool _isStdlib = isStdlib;
  private readonly string? _sourceFilePath = sourceFilePath;

  /// See <see cref="SourceFile.CompilerOwnedDeclarations"/>. Null for every ordinary compile.
  private readonly IReadOnlySet<string>? _compilerOwnedDeclarations = compilerOwnedDeclarations;

  /// <summary>
  /// The name of the function this compile enters through — <c>main</c> unless the caller named
  /// another (`maxon build`'s build-runner, `maxon test`'s dispatcher). Falls back to <c>main</c>
  /// when there is no module to ask, which is the parse-a-fragment case.
  ///
  /// Written once because three places ask it and one of them meant something subtly different: two
  /// ask "is this name UNQUALIFIED" (the entry, or `main`, keeps its bare name), and the third asks
  /// "is this THE entry" — and spelling the third as the first's disjunction emitted `__module_init`
  /// twice whenever a custom entry coexisted with a `main`, failing the build with E3006.
  /// </summary>
  private string EntryFunctionName => seedModule?.EntryFunctionName ?? "main";

  /// <summary>
  /// Whether <paramref name="baseName"/> keeps its bare, unqualified name rather than taking its
  /// file's namespace. Both the entry point and <c>main</c> do: a linker looks for one fixed symbol,
  /// and `main` stays callable as `main` even when the entry is something else.
  /// </summary>
  private bool KeepsUnqualifiedName(string baseName) =>
    baseName == "main" || baseName == EntryFunctionName;
  private readonly string _targetOs = targetOs;
  private readonly string _targetArch = targetArch;
  private readonly bool _testing = testing;
  // Per-file compile root. Every project-relative spelling of this file's path is measured
  // against it: the module namespace is rel(Path, RootPath).parent, and `__file__` is that
  // same relative path whole. See ProjectRelativePath.
  private readonly string? _rootPath = rootPath;
  private int _pos;

  // The call whose parameter defaults are being expanded right now, or null when no default
  // is being expanded. This is what `__line__` / `__file__` resolve against, and its nullness
  // IS the "only legal as a parameter default" rule: outside an expansion there is no call
  // site to name. Saved and restored around each fill so a default that itself contains a
  // call (whose callee has its own defaults) cannot leak its site to the outer one.
  private Token? _defaultArgCallSite;

  private IrModule<MaxonOp>? _currentModule;
  private IrFunction<MaxonOp>? _currentFunction;
  private IrBlock<MaxonOp>? _currentBlock;

  // Tracks the ranged primitive type name from the most recent construction expression (e.g., Age{42})
  private string? _lastRangedTypeName;
  // Set by ResolveExprValue: true when the resolved expression was a mutable variable reference
  private bool _lastExprWasMutableVar;
  // Set by ResolveExprValue: the variable name of the last resolved expression (null for non-variable expressions)
  private string? _lastExprVarName;
  // Set by ParseFieldAccessChain: true when the expression is rooted in an immutable variable
  // and does not end with .clone() (which creates an independent mutable copy)
  private bool _lastExprFromImmutableRoot;
  // Set by ParseCallArgs/ParseInstanceMethodCallArgs: per-argument mutability for the most recent call
  private List<bool>? _lastArgMutabilities;
  // Set by ParseCallArgs/ParseInstanceMethodCallArgs: per-argument variable names for the most recent call
  private List<string?>? _lastArgVarNames;
  private IrRangedPrimitiveType? _lastCastRangedType;
  // Temporarily set before calling TryEmitBuiltinManagedMemoryStaticMethod so it can resolve element kind
  private string? _managedMemStaticTypeName;
  // Temporarily set before calling TryEmitBuiltinTypeMethod so the synthetic builtin call ops
  // can record the receiver variable name in ArgVarNames[0]. The mutation analysis (E3019)
  // reads this to decide whether the call mutates a self-derived/self-field receiver.
  private string? _builtinReceiverVarName;

  // When parsing a static factory whose return type is the enclosing type,
  // records field names that have been assigned via `self.field = expr`. Each
  // assignment lowers to a local slot named `__self_<field>` — the deterministic
  // naming means we only need to remember *whether* a slot exists, not its name.
  // Null outside such factories. Reset at function end.
  private HashSet<string>? _nascentSelfAssignedFields;
  // True only while ParseReturn is evaluating its expression. Gating condition
  // for deferred-field initialization: a `Self{...}` literal can skip a field
  // whose value was assigned via `self.field = expr` only when the literal is
  // the direct return expression.
  private bool _parsingReturnExpression;
  // Each entry records a MaxonStructLiteralOp in a static factory whose missing
  // fields are supplied from `self.field = expr` writes. The post-body
  // definite-assignment pass validates that each deferred field was assigned on
  // every control-flow path before the literal.
  private readonly List<PendingFieldInitCheck> _pendingFieldInitChecks = [];

  private record PendingFieldInitCheck(
    IrBlock<MaxonOp> Block,
    int OpIndex,
    string TypeName,
    HashSet<string> DeferredFields,
    int Line,
    int Column);

  private readonly VarRegistry _variables = new();
  private readonly HashSet<string> _referencedVars = [];
  private int _blockCounter;
  // Stdlib and user closures use separate label namespaces so that the cached
  // stdlib's lifted closure functions never collide with user-code closures
  // whose counter resets each compile. A user `_$closure_0` and a stdlib
  // `_$closure_0` would otherwise both be added to the same module under the
  // same name, and only one wins in the function table.
  [ThreadStatic] private static int _closureCounter;
  [ThreadStatic] private static int _stdlibClosureCounter;
  public static void ResetClosureCounter() => _closureCounter = 0;
  private int _discardCounter;
  private readonly Stack<LoopContext> _loopStack = new();
  private readonly Stack<MatchContext> _matchStack = new();
  private bool _inTryContext;
  // Set while ParseStatement is invoked from a match-arm body. Consulted by
  // ParseTryBlock and EmitTryOtherwiseBlock to reject the multi-line block forms
  // of try (which would allocate persistent error-flag/discriminant slots in
  // the enclosing scope and leak them on every error path through the match).
  // Single-statement try forms are unaffected.
  private bool _inMatchArmBody;

  /// True while <see cref="ParseSynthesizedSource"/> is feeding the parser text the compiler wrote
  /// rather than text a program did. Only <see cref="CoverageActive"/> consults it, and the reason
  /// is recorded there.
  private bool _inSynthesizedSource;

  /// Active try-block contexts (for the new `try 'label' ... end 'label' otherwise (e) ...` form).
  /// While the stack is non-empty, bare calls to throwing functions inside the body do not require
  /// the `try` keyword — the parser implicitly promotes them to `MaxonTryCallOp` and routes their
  /// error flag to the block's shared error sink. The active context is the innermost (top of stack).
  private readonly Stack<TryBlockContext> _tryBlockStack = new();

  /// State for an active `try` block. Bare throwing calls inside the body funnel their
  /// error flags into ErrorFlagVarName and discriminants into TypeDiscriminantVarName,
  /// then branch to ErrorBlockLabel. ErrorTypesEncountered preserves insertion order so
  /// the union's member discriminant indices are deterministic.
  private sealed class TryBlockContext {
    public required string ErrorBlockLabel { get; init; }
    public required string ErrorFlagVarName { get; init; }
    public required string TypeDiscriminantVarName { get; init; }
    public required string BlockLabel { get; init; }
    // Snapshot of variable keys captured at try-block entry. Each routed bare
    // throw uses this with VarRegistry.KeysSince to compute the body-local
    // managed temps live at the throw site — without this, ephemeral call-arg
    // allocations (e.g. `f(IntArray.create())`) leak when `f` throws.
    public required HashSet<string> BodyOuterScope { get; init; }
    public List<IrEnumType> ErrorTypesEncountered { get; } = [];
    // Pending landing pads: each routed bare throw inside the body deposits
    // its (label, body-local-temps-live-at-throw) here; ParseTryBlock emits the
    // actual blocks after the body finishes so they are appended at the END of
    // the function body and don't disrupt the codegen's fall-through assumption
    // for the cond_br's success target (which must be the next physical block).
    public List<(string Label, List<string> LiveBodyTemps)> PendingLandingPads { get; } = [];

    public int IndexOfOrAddType(IrEnumType t) {
      for (int i = 0; i < ErrorTypesEncountered.Count; i++) {
        if (ErrorTypesEncountered[i].Name == t.Name) return i;
      }
      ErrorTypesEncountered.Add(t);
      return ErrorTypesEncountered.Count - 1;
    }
  }

  // True while parsing the iterable expression of a `for-in` header. Suppresses
  // the expression-level `to`/`upto` -> Range/OpenRange.create lowering so the
  // for-in parser can recognize the trailing `to`/`upto` token itself and use
  // its fast-path while-loop desugaring.
  private bool _inForInIterable;
  private MaxonCallOp? _lastExprCallOp;
  // True when the most recently parsed expression was a `__Builtins.*` static
  // intrinsic call. These emit specialized ops (MaxonManagedWriteStdoutOp,
  // runtime-call ops, …) rather than a MaxonCallOp, so the `_ = expr` discard
  // validation — which otherwise only recognizes MaxonCallOp / MaxonTryCallOp —
  // needs this signal to treat a builtin call as the function call it is.
  private bool _lastExprWasBuiltinCall;
  private bool _parsingTypeAliasRhs;
  // True only while parsing the topmost typeref of a typealias RHS. Inline
  // `function(...) returns T` types are only valid when this flag is set.
  private bool _atTopOfTypeAliasRhs;
  private bool _skipWhereValidation;
  private readonly Dictionary<string, IrType> _typeRegistry = SeedTypeRegistry(seedModule, sourceFilePath);

  /// <summary>
  /// ⭐ WHAT EACH TYPE NAME MEANS TO THIS FILE — the one seam at which a reading file is handed
  /// another file's declaration, and therefore the one place a SCOPE can be given to a table that has
  /// none.
  ///
  /// <c>IrModule.TypeDefs</c> is keyed by bare name and holds ONE entry, so where a name is declared
  /// in two files it answers for every reader with whichever declaration merged last. MEASURED at
  /// this rung's merge base, both directions of the same fact: a file in <c>Compiler/</c> casting to
  /// its own directory's <c>Tally</c> got <c>Compiler/Coverage/</c>'s range (<c>E3005: Value 200 is
  /// outside the range of 'Tally' (int(-100 to 100))</c>), and a file in <c>scopeA/</c> naming its own
  /// subtree's <c>module</c> alias was told <c>E2003: Unknown type: Cell</c>, because the single
  /// <c>TypeDefSourceFiles</c> entry named the other subtree's declarer and the visibility test read
  /// it.
  ///
  /// ⚠ THE SCOPED PATH IS TAKEN ONLY WHERE THE FLAT TABLE CANNOT HOLD BOTH — a name with two or more
  /// declaring files. With one declaration there is nothing to choose between, and the existing
  /// visibility filter is the whole answer; routing every name through the scope rule would be a
  /// second, wider reading of visibility standing beside <see cref="IsTypeVisibleAcrossFiles"/>,
  /// which is the shape this rung exists to remove rather than to add.
  /// </summary>
  private static Dictionary<string, IrType> SeedTypeRegistry(IrModule<MaxonOp>? seedModule, string? sourceFilePath) {
    var registry = new Dictionary<string, IrType>();
    if (seedModule == null) return registry;

    foreach (var typeName in seedModule.TypeDefs.Keys)
      if (TryTypeAsSeenFrom(seedModule, typeName, sourceFilePath, out var type)) registry[typeName] = type;

    return registry;
  }

  /// <summary>
  /// ⭐ WHAT <paramref name="typeName"/> MEANS TO A FILE AT <paramref name="accessorPath"/> — WHICH
  /// declaration governs it and WHAT that declaration binds the name to, answered in one call.
  ///
  /// ⚠ THEY ARE ONE QUESTION, AND SPLITTING THEM IS THE DEFECT ITSELF. Asked of two maps — the choice
  /// through the scoped sites, the payload from the flat, bare-name-keyed <c>TypeDefs</c> — they can
  /// answer about two DIFFERENT declarations, which is exactly why the type travels in
  /// <see cref="AliasSite.DeclaredType"/> rather than in a table beside it. The constant folder's
  /// foreign-perspective lookup (<see cref="TryResolveForeignConstFoldType"/>) was doing precisely
  /// that: it gated on the scoped visibility rule and then handed back <c>TypeDefs</c>'s single
  /// entry, which for a name two files declare is whichever merged last.
  ///
  /// <c>false</c> means the name is not a type this reader may write: either no declaration of it
  /// governs <paramref name="accessorPath"/>, or — for a name with at most one declaring file, where
  /// the flat tables describe it exactly — the visibility filter says no.
  /// </summary>
  private static bool TryTypeAsSeenFrom(IrModule<MaxonOp> seedModule, string typeName,
      string? accessorPath, [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out IrType? type) {
    type = null;
    if (TryGoverningDeclaration(seedModule, typeName, accessorPath, out var governing)) {
      // A name with no governing declaration is not a fallback to the flat entry: it is this reader
      // standing outside every scope the name was declared in, and the name is not a type here.
      if (governing is not { } nearest) return false;

      type = nearest.DeclaredType ?? seedModule.TypeDefs.GetValueOrDefault(typeName);
      return type != null;
    }

    if (!IsTypeVisibleAcrossFiles(seedModule, typeName, accessorPath)) return false;

    return seedModule.TypeDefs.TryGetValue(typeName, out type);
  }

  // Cross-file type visibility used by the parser-ctor seed filter and by
  // IsNonExportedCrossFileType. Returns true if a type with the given name
  // declared in `seedModule` should be visible to a parser running on
  // `accessorPath`. The rules:
  //   - A name TWO OR MORE files declare is the scope table's question, not
  //     these three tables' — see the note below.
  //   - Exported types (not in NonExportedTypeNames and not in
  //     ModuleVisibleTypeNames) are always visible.
  //   - File-scoped types (in NonExportedTypeNames) are visible only if the
  //     accessor is in the same source file.
  //   - Module-scoped types are visible if same file OR accessor is within
  //     the declarer's directory subtree.
  private static bool IsTypeVisibleAcrossFiles(IrModule<MaxonOp> seedModule, string typeName, string? accessorPath) {
    // ⭐ The three tables below hold ONE record per name, so for a name two files declare they
    // describe one declaration and answer for readers of the other: `TypeDefSourceFiles` named the
    // OTHER subtree's declarer, and a file naming its own subtree's `module typealias Cell` was told
    // `E2003: Unknown type: Cell`.
    if (TryGoverningDeclaration(seedModule, typeName, accessorPath, out var governing))
      return governing != null;

    bool isFileScoped = seedModule.NonExportedTypeNames.Contains(typeName);
    bool isModuleVisible = seedModule.ModuleVisibleTypeNames.Contains(typeName);
    if (!isFileScoped && !isModuleVisible) return true; // exported / public
    if (!seedModule.TypeDefSourceFiles.TryGetValue(typeName, out var declarerPath)) return true;
    if (accessorPath == null) return true;
    if (declarerPath == accessorPath) return true;
    if (isModuleVisible && AliasScope.IsInDirectoryScopeOf(declarerPath, accessorPath)) return true;
    return false;
  }

  /// <summary>
  /// ⭐ WHETHER <paramref name="typeName"/> IS A QUESTION ONLY THE SCOPE TABLE CAN ANSWER, and if so
  /// which declaration of it governs <paramref name="accessorPath"/> — the ONE spelling of that, for
  /// the two readers that need it.
  ///
  /// There are three answers here and they must not be collapsed into two. <c>false</c> means the
  /// name has at most one declaration, so the flat, bare-name-keyed tables describe it exactly and
  /// are the answer. <c>true</c> with a site means that declaration governs this reader. <c>true</c>
  /// with none means the reader stands outside every scope the name was declared in, and the name is
  /// not a type here at all — which is NOT the same as falling back to a flat entry describing
  /// somebody else's declaration.
  ///
  /// ⚠ IT EXISTS BECAUSE THE SEED AND THE VISIBILITY TEST ARE ONE FACT AND WERE TWO READERS OF IT.
  /// The registry seed was made scope-aware first and the program was still refused: `ParseTypeRef`
  /// asks <see cref="IsNonExportedCrossFileType"/> BEFORE its own registry lookup, and that path went
  /// on reading <c>TypeDefSourceFiles</c>'s single entry. A cure applied at one of two readers of one
  /// fact survives at the other, which is this rung's own family.
  /// </summary>
  private static bool TryGoverningDeclaration(IrModule<MaxonOp> seedModule, string typeName,
      string? accessorPath, out AliasSite? governing) {
    governing = null;
    if (accessorPath == null) return false;
    if (!seedModule.AliasDeclarationSites.TryGetValue(typeName, out var sites) || sites.Count <= 1)
      return false;

    governing = AliasScope.NearestDeclarationFor(sites, accessorPath);
    return true;
  }

  // Types registered during this parser's PreScan — only these get auto-conformance synthesis
  private readonly HashSet<string> _locallyDefinedTypes = [];
  // Function values that carry a capture ENVIRONMENT, mapped to the name of the function
  // frame that DEFINED them, and the local names bound to such a value (likewise mapped).
  // See ErrorCode.SemanticCapturingClosureEscapes: captures are taken by reference to the
  // defining frame, so such a value may not outlive that frame.
  //
  // The frame is what makes the rule exactly "may not escape ITS DEFINING frame" rather
  // than the blunter "may not be returned". Returning a closure from the frame that built
  // it dangles; returning one that an OUTER frame built does not, because the environment
  // it points at belongs to that still-live outer frame. Only the former is refused.
  //
  // Membership is the whole test for "does this value carry an environment?": only a
  // MaxonClosureCreateOp result is ever entered here, because a closure that captures
  // nothing lowers to a plain MaxonFunctionRefOp and has no environment to lose.
  private readonly Dictionary<int, string> _capturingClosureFrames = [];
  private readonly Dictionary<string, string> _capturingClosureVarFrames = [];
  private string? _currentTypeName;
  // SSA result of the `self` MaxonStructParamOp for the currently-parsing instance
  // method. Used by InvalidateCachedSelfFields() to re-emit MaxonFieldAccessOps
  // after function calls that may have mutated self-field aliases. Null when
  // parsing top-level / non-instance / non-struct-self functions.
  private MaxonValue? _currentSelfParamResult;
  // Self-field aliases whose cached SSA value is potentially stale (last touched
  // by a function call that may have written to the field via the heap). The
  // next read in the current block emits a fresh MaxonFieldAccessOp and clears
  // the entry. Reset on function-body entry / exit alongside
  // _currentSelfParamResult.
  private readonly HashSet<string> _staleSelfFields = [];

  /// <summary>
  /// ⭐⭐ Every `u64.max` written in EXPRESSION position, by the id of the literal it materialized —
  /// the ONE constant whose stored pattern is negative and whose value is not.
  ///
  /// `u64.max` does not fit a signed 64-bit field, so it rides as the wrapped `-1`
  /// (<see cref="ResolveIntTypeBound"/>). Every reader that asks "is this operand non-negative?" by
  /// testing the folded constant therefore answers NO for the largest non-negative number there is,
  /// which is a wrong answer rather than a missed narrowing: with `x` declared `int(0 to u64.max)`,
  /// `x &gt; u64.max` compiled to a SIGNED `jg` against `-1` and answered <b>true</b>.
  ///
  /// ⚠ It cannot be re-derived from the value, and must not be: a literal `-1` the author actually
  /// wrote is the same 64 bits and is a genuinely negative operand — `x &gt; -1` is TRUE at every
  /// value of `x`, and reading that `-1` as `u64.max` would answer false. Only the source tells them
  /// apart, so the parse site records it and <see cref="ComparisonOperandIsUnsigned"/> reads it.
  ///
  /// Keyed by MaxonValue id, which is sound because every literal mints a fresh value (no interning).
  /// shv2 carries the identical fact in `Parser.unsignedMaxLiterals`, marked and read at the same two
  /// points, so the two compilers answer one question the same way.
  /// </summary>
  private readonly HashSet<int> _unsignedMaxLiterals = [];

  private readonly List<CompileError> _errors = [];
  private const int MaxErrorsPerFile = 20;
  public IReadOnlyList<CompileError> Errors => _errors;

  /// The name `Self` carries in a type position — always "the enclosing/receiving type". It is a
  /// keyword (TokenType.SelfType), so no user type can collide with it. Named here because the
  /// parser tests for it in four unrelated places and each spelling is the same one fact.
  private const string SelfTypeName = "Self";

  /// The name of an instance method's receiver PARAMETER, as it appears in the parameter list the
  /// parser builds — distinct from <see cref="SelfTypeName"/>, which is the type. Named because the
  /// overload mangle, the mangle-with-types and the signature renderer each have to leave it out,
  /// and a diagnostic that names it names something the reader cannot find in their source.
  private const string SelfParamName = "self";

  /// The discard identifier. Writing it declares no binding and is exempt from the unused checks,
  /// which is how a result gets dropped on purpose (`_ = f()`, `if let _ = try f()`, `for _ in xs`,
  /// a match payload). Named here because eight unrelated places test for it and every one of them
  /// is the same one fact — `specs/discarded-results.md` is where that fact is written down.
  private const string DiscardIdentifier = "_";

  // Top-level compile-time constants (name -> evaluated value: long, double, or bool)
  private Dictionary<string, object> _topLevelConstants = [];

  // While folding a FOREIGN constant, the path of the file that DECLARES it — the perspective a
  // cast/enum type name must be resolved from, so `let X = 5 as PrivateAlias` folds against the
  // declarer's private aliases and not the demander's registry. Null while folding the current
  // file's own constants (whose aliases are already in _typeRegistry).
  private string? _constFoldPerspectivePath;

  // The current file's visible constant set, captured once per fold. It anchors the circular-
  // dependency BLAME to the demanding file (matching the resolver before it folded in the
  // declarer's perspective) and gates which folded values may be published to the name-keyed
  // _topLevelConstants — a declarer's private must never leak into the current file's table.
  private ConstantDeclSet _currentFileConstantDecls = ConstantDeclSet.Empty;

  // Memo of ConstantDeclSetFor: a FOREIGN file's visible-constant set built once and reused, so
  // folding in a declarer's perspective stays O(1) amortized rather than rescanning the whole-program
  // declaration list per reference (the quadratic the optimizer removed). A foreign perspective is a
  // pure function of the module's whole-program constant declarations (fixed before folding) and a
  // file path — never of parser state — so the cache is SHARED across every parser in a compilation
  // when one is supplied: a fresh Parser is created for each file in each pass, and a per-parser cache
  // made every parser rebuild the same declarer's perspective, so total build work grew
  // super-quadratically on deep cross-file constant chains folded in a seeding-defeating order. The
  // current file's OWN set (_currentFileConstantDecls) is never stored here — it is built from this
  // parser's own token walk, and only foreign folds read this cache. Typed as object because the
  // shared cache is threaded in from CompileSources, which cannot name the parser-private value type;
  // every value is a ConstantDeclSet.
  private readonly Dictionary<string, object> _constantDeclSetCache = foreignPerspectiveCache ?? [];

  // Top-level declarations deferred for evaluation at a later phase
  private record EnumConstantValue(string EnumTypeName, string CaseName, int Ordinal);
  /// Shared info for both try-call and try-await operations, used by the otherwise-clause helpers.
  private record TryResultInfo(MaxonInteger ErrorFlag, MaxonValue? Result, MaxonValueKind? ResultKind, string? ResultStructTypeName, IrType? CalleeReturnType = null, IrFunctionType? ResultFnType = null);
  private record DeferredDecl(string Name, int TokenStart, int TokenEnd, int Line, int Column, bool IsExported = false, bool IsModuleVisible = false);
  private readonly List<DeferredDecl> _deferredExprLets = [];
  private readonly List<DeferredDecl> _deferredGlobalVars = [];
  private readonly List<DeferredDecl> _deferredExprVars = [];

  // Lazy static fields (initialized on first access)
  private record LazyStaticField(string QualifiedName, string GuardName, List<Token> Tokens, int TokenStart, int TokenEnd, bool IsMutable, int Line, int Column);
  private readonly List<LazyStaticField> _lazyStaticFields = [];

  // Global mutable variables (name -> type info)
  private readonly Dictionary<string, GlobalVarMetadata> _globalVars = [];

  // Unified variable resolution result
  private abstract record ResolvedVar {
    public record Local(VarInfo Info) : ResolvedVar {
      public override bool IsMutable => Info.Mutable;
    }
    public record Global(GlobalVarMetadata Info) : ResolvedVar {
      public override bool IsMutable => Info.Mutable;
    }
    public abstract bool IsMutable { get; }
  }

  // Default parameter values (funcName -> index -> value)
  private readonly Dictionary<string, Dictionary<int, IrAttribute>> _functionDefaults = [];

  // Type alias source tracking (aliasName -> sourceTypeName)
  private readonly Dictionary<string, string> _typeAliasSources = [];

  // Export tracking for types, enums, and typealiases defined in this file
  private readonly HashSet<string> _exportedTypes = [];
  private readonly HashSet<string> _exportedTypeAliases = [];
  // Module-visibility tracking: declarations marked `module` (visible across the
  // current directory subtree). Mutually exclusive with _exportedTypes /
  // _exportedTypeAliases — enforced at the parser modifier site.
  private readonly HashSet<string> _moduleVisibleTypes = [];
  private readonly HashSet<string> _moduleVisibleTypeAliases = [];
  private readonly HashSet<string> _localTypeAliases = [];
  // Which pass over this file's top-level typealiases is running (see TypeAliasScanPhase).
  private TypeAliasScanPhase _typeAliasScanPhase = TypeAliasScanPhase.Specialize;
  // Set when PreScanTypeAliasesOnly is running as a re-scan (third pass) to
  // force CopyTypeAliasesToModule to overwrite entries for aliases this parser
  // locally (re-)declared, even though SeedFromModule marked them as seeded.
  private bool _isRescanningTypeAliases;
  // Declared aliases this parser is registering on behalf of the file that declares them, to stop a
  // mutually-referential pair of declarations recursing forever through TryRegisterDeclaredAlias.
  private readonly HashSet<string> _registeringDeclaredAliases = [];
  // Aliases this parser registered on behalf of ANOTHER file's declaration -> that file. The module's
  // record for an alias has to name its declarer, not whoever happened to need it first.
  private readonly Dictionary<string, string> _borrowedAliasOwners = [];
  private readonly Dictionary<string, string> _typeAliasOwners = [];  // typealias name -> owning type name
  private readonly HashSet<string> _seededTypeAliases = [];
  private readonly HashSet<string> _seededStdlibTypeAliases = [];
  private readonly HashSet<string> _usedTypeAliases = [];
  private readonly Dictionary<string, (int Line, int Column)> _typeAliasLocations = [];
  // Inner ranged typealiases collected during type body parsing, keyed by owning type name.
  // Applied to the completed struct after the type body is fully parsed.
  private readonly Dictionary<string, Dictionary<string, IrRangedPrimitiveType>> _pendingInnerRangedAliases = [];
  private readonly HashSet<string> _resolvingTypeAliases = [];

  // Extension conformance loop tracking: when processing extension typealiases for each
  // conforming type, maps unqualified alias names to per-conforming-type mangled names
  // (e.g., "EnumSelf" -> "__EnumeratedIterator_ArrayIterator_Integer") so IR references
  // use unique names instead of the shared alias name that gets overwritten.
  private bool _inExtensionConformanceLoop;
  private readonly Dictionary<string, string> _extensionAliasToMangled = [];

  // The structural name this file's declaration of a CONTESTED alias was minted under — the same
  // fact _extensionAliasToMangled carries, for the other mint. See TryResolveAliasSpelling for why
  // they are two maps and one reader, and IrModule.ContestedGenericAliasNames for the mint itself.
  private readonly Dictionary<string, string> _contestedAliasInstanceNames = [];

  // Interface associated type names (interfaceName -> list of associated type names from 'uses' clause)
  private readonly Dictionary<string, List<string>> _interfaceAssociatedTypes = [];

  // Primitive type interface conformances from extension blocks (e.g., "int" -> ["Hashable", "Equatable"])
  private readonly Dictionary<string, List<string>> _primitiveConformances = seedModule != null
    ? new(seedModule.PrimitiveConformances.Select(kv => new KeyValuePair<string, List<string>>(kv.Key, [.. kv.Value]))) : [];

  // Conditional conformances from extension blocks on generic types
  // e.g., "extension Array implements Hashable where Element is Hashable" -> ("Array", ["Hashable"], {"Element": ["Hashable"]})
  private readonly List<(string SourceTypeName, List<string> Interfaces, Dictionary<string, List<string>> WhereConstraints)> _conditionalConformances = seedModule != null
    ? [.. seedModule.ConditionalConformances] : [];

  // Tracks conditional extension methods skipped due to unsatisfied where-constraints
  // Key: "TypeName.methodName", Value: (paramName, requiredInterface, concreteTypeName)
  private readonly Dictionary<string, (string ParamName, string RequiredInterface, string ConcreteTypeName)> _skippedConditionalExtensions = [];

  /// <summary>
  /// Creates a unique mangled name for an overloaded function by appending
  /// distinguishing parameter names. For instance methods, 'self' is excluded.
  /// The first non-self parameter name is also excluded (since it's positional and
  /// the same across overloads). Only subsequent named params form the suffix.
  /// Example: slice(self, start, endIndex) -> baseName$endIndex
  /// </summary>
  private static string MangleOverloadName(string baseName, List<string> paramNames) {
    var nonSelf = paramNames.Where(n => n != SelfParamName).ToList();
    if (nonSelf.Count == 0) return baseName;
    // For 1-param overloads, use param name directly; for 2+, skip the first positional
    var distinguishing = nonSelf.Count == 1 ? nonSelf : nonSelf.Skip(1);
    return $"{baseName}${string.Join("_", distinguishing)}";
  }

  /// <summary>
  /// Creates a mangled name that includes both parameter names and types,
  /// used when name-only mangling produces a collision (same param names, different types).
  /// Example: process(value int) -> baseName$value_i64, process(value String) -> baseName$value_String
  /// </summary>
  private static string MangleOverloadNameWithTypes(string baseName, List<string> paramNames, List<IrType> paramTypes) {
    var parts = new List<string>();
    for (int i = 0; i < paramNames.Count; i++) {
      if (paramNames[i] == SelfParamName) continue;
      parts.Add($"{paramNames[i]}_{TypeMangledSuffix(paramTypes[i])}");
    }
    if (parts.Count == 0) return baseName;
    return $"{baseName}${string.Join("_", parts)}";
  }

  private static string TypeMangledSuffix(IrType type) => type switch {
    IrStructType st => st.Name,
    IrEnumType et => et.Name,
    IrFunctionType => "fn",
    IrTypeParameterType tp => tp.ParameterName,
    IrRangedPrimitiveType rpt => rpt.BaseType.Name,
    _ => type.Name
  };

  /// <summary>
  /// Extracts the base function name from a potentially mangled overload name.
  /// "stdlib.String.slice$endIndex" -> "stdlib.String.slice"
  /// </summary>
  private static string UnmangleName(string mangledName) {
    var dollarIdx = mangledName.IndexOf('$');
    return dollarIdx >= 0 ? mangledName[..dollarIdx] : mangledName;
  }

  /// <summary>
  /// Detects overloads for a function being registered and returns the mangled registration name.
  /// If existing functions with the same base name exist, retroactively mangles them
  /// and returns a mangled name for the new function. Updates _functionDefaults
  /// dictionary when renaming existing functions.
  /// Supports both name-based and type-based disambiguation.
  /// </summary>
  private string ResolveOverloadRegistrationName(IrModule<MaxonOp> module, string baseName,
      List<string> paramNames, List<IrType> paramTypes, Token site, bool isStatic = false) {
    // Look up by overload base name (UnmangleName strips the $... tail), which the
    // IrModule base-name index matches directly. Also include any literal same-named
    // entry for parity with the prior `f.Name == baseName` clause.
    var existingOverloads = new List<IrFunction<MaxonOp>>(module.FindFunctionsByBaseName(baseName));
    var exact = module.FindFunctionByExactName(baseName);
    if (exact != null && !existingOverloads.Contains(exact))
      existingOverloads.Add(exact);

    if (existingOverloads.Count == 0) {
      return baseName;
    }

    // If the only existing match has the exact same signature, it's the same function
    // (e.g., re-registration during full parse after pre-scan)
    if (existingOverloads.Count == 1 && existingOverloads[0].Name == baseName
        && existingOverloads[0].ParamNames.SequenceEqual(paramNames)
        && ParamTypesMatch(existingOverloads[0].ParamTypes, paramTypes)) {
      return baseName;
    }

    var registrationName = MangleOverloadName(baseName, paramNames);

    // Check if this exact function was already registered under a type-augmented name
    var typeMangledForNew = MangleOverloadNameWithTypes(baseName, paramNames, paramTypes);
    var existingTypeMangled = existingOverloads.FirstOrDefault(f => f.Name == typeMangledForNew);
    if (existingTypeMangled != null) {
      // Same function re-registered (e.g., during full parse after pre-scan)
      if (existingTypeMangled.ParamNames.SequenceEqual(paramNames)
          && ParamTypesMatch(existingTypeMangled.ParamTypes, paramTypes))
        return typeMangledForNew;
    }

    // Retroactively mangle any existing function that still has the unmangled name
    foreach (var existing in existingOverloads) {
      if (!existing.Name.Contains('$')) {
        var mangledExisting = MangleOverloadName(baseName, existing.ParamNames);
        if (mangledExisting == registrationName) {
          // Same function re-registered (e.g., from pre-scan)
          if (existing.ParamNames.SequenceEqual(paramNames)
              && ParamTypesMatch(existing.ParamTypes, paramTypes))
            return registrationName;

          // Name-based collision but different types — use type-augmented mangling
          var typeMangledExisting = MangleOverloadNameWithTypes(baseName, existing.ParamNames, existing.ParamTypes);
          if (typeMangledExisting == typeMangledForNew) {
            return ResolveStaticInstanceCollision(module, existing, baseName, baseName, isStatic,
              paramNames, paramTypes, site);
          }

          var oldName2 = existing.Name;
          module.RenameFunction(existing, typeMangledExisting);
          if (_functionDefaults.Remove(oldName2, out var existingDefaults)) {
            _functionDefaults[typeMangledExisting] = existingDefaults;
          }
          return typeMangledForNew;
        }
        var oldExistingName = existing.Name;
        module.RenameFunction(existing, mangledExisting);
        if (_functionDefaults.Remove(oldExistingName, out var defaults)) {
          _functionDefaults[mangledExisting] = defaults;
        }
      } else if (existing.Name == registrationName) {
        // Already mangled with same name — check if it's a re-registration or type collision
        if (existing.ParamNames.SequenceEqual(paramNames)
            && ParamTypesMatch(existing.ParamTypes, paramTypes))
          return registrationName;

        // Name-based collision on already-mangled function — re-mangle both with types
        var typeMangledExisting = MangleOverloadNameWithTypes(baseName, existing.ParamNames, existing.ParamTypes);
        if (typeMangledExisting == typeMangledForNew) {
          return ResolveStaticInstanceCollision(module, existing, registrationName, baseName, isStatic,
            paramNames, paramTypes, site);
        }

        var oldName3 = existing.Name;
        module.RenameFunction(existing, typeMangledExisting);
        if (_functionDefaults.Remove(oldName3, out var existingDefaults)) {
          _functionDefaults[typeMangledExisting] = existingDefaults;
        }
        return typeMangledForNew;
      }
    }

    return registrationName;
  }

  private static bool ParamTypesMatch(List<IrType> a, List<IrType> b) {
    if (a.Count != b.Count) return false;
    for (int i = 0; i < a.Count; i++) {
      if (TypeMangledSuffix(a[i]) != TypeMangledSuffix(b[i])) return false;
    }
    return true;
  }

  /// <summary>
  /// Handle static/instance collision where two functions have the same type-mangled signature
  /// but differ in static vs instance. Disambiguates by appending ~static to the static method's name.
  /// </summary>
  private string ResolveStaticInstanceCollision(
      IrModule<MaxonOp> module, IrFunction<MaxonOp> existing,
      string currentName, string baseName, bool isStatic,
      List<string> paramNames, List<IrType> paramTypes, Token site) {
    if (isStatic != existing.IsStatic) {
      var staticName = currentName + "~static";
      if (isStatic) {
        return staticName;
      }
      // Existing is the static one — rename it
      var oldName = existing.Name;
      module.RenameFunction(existing, staticName);
      if (_functionDefaults.Remove(oldName, out var staticDefaults)) {
        _functionDefaults[staticName] = staticDefaults;
      }
      return currentName;
    }

    // ⚠ A DISTINCT PAIR OF OVERLOADS ARRIVED HERE AND WAS REPORTED AS A REDECLARATION, out of an
    // InvalidOperationException — E9001 plus a C# stack trace, which is what an INTERNAL failure
    // looks like, on a program that has none.
    //
    // The overload mangle joins `{paramName}_{type}` parts with `_`, and `_` is legal inside both a
    // parameter name and a type name, so the join is not injective: `f(x_i64_y P, w R)` and
    // `f(x i64_y_P, w R)` are two distinct signatures that mangle to one name. Measured — the
    // message said they "have the same signature", which is exactly what they do not have, and named
    // neither. It is the same non-injective join as AdoptOrMintConcreteInstance's, one namespace
    // along, and it is refused with the same code and the same shape of words.
    //
    // ⚠ A GENUINE REDECLARATION NEVER REACHES THIS, and the assertion below says so rather than
    // carrying a second user-facing message that could not fire: both callers return early on
    // exactly this predicate, and E3006 `Duplicate function` already refuses the same-signature pair
    // (measured) further up.
    if (existing.ParamNames.SequenceEqual(paramNames) && ParamTypesMatch(existing.ParamTypes, paramTypes))
      throw new InvalidOperationException(
        $"ResolveStaticInstanceCollision was called for '{currentName}' with the incumbent's own "
        + "signature; both callers establish that the two signatures differ before calling.");

    throw new CompileError(ErrorCode.SemanticDuplicateDefinition,
      $"duplicate definition of '{currentName}' - the overloads "
      + $"`{FormatParameterList(baseName, existing.ParamNames, existing.ParamTypes)}` and "
      + $"`{FormatParameterList(baseName, paramNames, paramTypes)}` compile to that same name",
      site.Line, site.Column);
  }

  /// <summary>
  /// Resolves a qualified method name, falling back to the source type for type aliases.
  /// E.g., "ByteArray.push" → looks for "ByteArray.push" first, then "Array.push".
  /// Also supports suffix matching for namespace-qualified names.
  /// Returns the resolved function name if found, null otherwise.
  /// </summary>
  private string? ResolveMethodName(string qualifiedName) {
    // Check for exact match
    if (_currentModule!.FindFunctionByExactName(qualifiedName) != null)
      return qualifiedName;

    // Check for mangled overload variants (exact prefix with '$'). The base-name
    // index returns every function whose base (minus $overload tail) equals
    // qualifiedName, which is exactly the old `StartsWith(qualifiedName + "$")`
    // check minus the bare-equal case already handled above.
    var baseMatches = _currentModule!.FindFunctionsByBaseName(qualifiedName);
    if (baseMatches.Count > 0)
      return qualifiedName; // return base name; overload resolution happens downstream

    // Try suffix match (for namespace-qualified names). Unqualified single
    // segments go through the short-name index; qualified (multi-segment)
    // names go through the qualified-suffix index. Both indices key on the
    // overload-stripped base name, so mangled variants (`.qualifiedName$T`)
    // land under the same bucket as their base.
    List<IrFunction<MaxonOp>> suffixMatches;
    if (qualifiedName.IndexOf('.') < 0) {
      suffixMatches = [.. _currentModule!.FindFunctionsByShortName(qualifiedName)];
    } else {
      suffixMatches = [.. _currentModule!.FindFunctionsByQualifiedSuffix(qualifiedName)];
    }
    if (suffixMatches.Count == 1)
      return suffixMatches[0].Name;
    if (suffixMatches.Count > 1) {
      // Multiple matches - check if they are all overloads of the same base name
      var baseNames = suffixMatches.Select(f => UnmangleName(f.Name)).Distinct().ToList();
      if (baseNames.Count == 1)
        return baseNames[0]; // all overloads of one function; return base name for downstream resolution
      // Truly ambiguous - caller will need to handle this
      return null;
    }

    var dotIdx = qualifiedName.IndexOf('.');
    if (dotIdx > 0) {
      var typePart = qualifiedName[..dotIdx];
      var methodPart = qualifiedName[(dotIdx + 1)..];

      // Where-constraint fallback: if typePart is a type parameter with constraints,
      // resolve via the constrained interface methods
      if (_currentTypeName != null
          && _typeRegistry.TryGetValue(_currentTypeName, out var currentType)
          && currentType is IrStructType currentStruct
          && currentStruct.WhereConstraints.TryGetValue(typePart, out var constrainedInterfaces)) {
        foreach (var ifaceName in constrainedInterfaces) {
          var ifaceMethodName = $"{ifaceName}.{methodPart}";
          var resolved = ResolveMethodName(ifaceMethodName);
          if (resolved != null) return resolved;
        }
      }

      // Interface conformance fallback: MaxonModule.merge → MergeableModule.merge
      if (_typeRegistry.TryGetValue(typePart, out var typeEntry)) {
        HashSet<string>? conforming = typeEntry switch {
          IrStructType st => st.ConformingInterfaces,
          IrEnumType et => et.ConformingInterfaces,
          _ => null
        };
        if (conforming != null) {
          foreach (var ifaceName in conforming) {
            var ifaceMethodName = $"{ifaceName}.{methodPart}";
            var resolved = ResolveMethodName(ifaceMethodName);
            if (resolved != null) return resolved;
          }
        }
      }

      // Try alias fallback: ByteArray.push → Array.push
      if (_typeAliasSources.TryGetValue(typePart, out var sourceType)) {
        _usedTypeAliases.Add(typePart);
        var aliasedName = $"{sourceType}.{methodPart}";
        if (_currentModule!.FindFunctionByExactName(aliasedName) != null)
          return aliasedName;
        // Check for mangled overload variants of aliased name
        if (_currentModule!.FindFunctionsByBaseName(aliasedName).Count > 0)
          return aliasedName;
        // Try suffix match on aliased name too — aliasedName is always qualified
        // (Type.method) so it lands in the qualified-suffix index.
        var aliasSuffixMatches = _currentModule!.FindFunctionsByQualifiedSuffix(aliasedName);
        if (aliasSuffixMatches.Count == 1)
          return aliasSuffixMatches[0].Name;
        if (aliasSuffixMatches.Count > 1) {
          var aliasBaseNames = aliasSuffixMatches.Select(f => UnmangleName(f.Name)).Distinct().ToList();
          if (aliasBaseNames.Count == 1)
            return aliasBaseNames[0];
        }
      }
    }
    return null;
  }

  /// Resolve a qualified method name, preferring the ~static variant when both a static
  /// and instance method share the same name. Used for Type.method() call sites.
  private string? ResolveStaticMethodName(string qualifiedName) {
    return ResolveMethodName(qualifiedName + "~static") ?? ResolveMethodName(qualifiedName);
  }

  /// Pick the registered name for a method on <paramref name="typeName"/> when
  /// synthesizing a derived method body (auto-clone / auto-equals). The nested
  /// type may live in a different namespace than the enclosing type (e.g. a
  /// Testing/ struct with a String field — String.clone is stdlib.String.clone,
  /// not Testing.String.clone). Probe order: enclosing namespace, exact name,
  /// qualified-suffix index, short-name index, alias chase. Falls back to
  /// `{currentNamespace}.{typeName}.{methodName}` when nothing matches so the
  /// resulting MaxonCallOp surfaces the synthesizer's intent in the diagnostic
  /// rather than a stripped name.
  private string ResolveSynthesizedMethodName(IrModule<MaxonOp> module, string typeName, string methodName, string currentNamespace) {
    // Try the enclosing namespace first — most common case for a type that
    // declares both itself and the nested field-type in the same module.
    if (!string.IsNullOrEmpty(currentNamespace)) {
      var localCandidate = $"{currentNamespace}.{typeName}.{methodName}";
      if (module.FindFunctionByExactName(localCandidate) != null) return localCandidate;
    }
    var bareCandidate = $"{typeName}.{methodName}";
    if (module.FindFunctionByExactName(bareCandidate) != null) return bareCandidate;
    // Suffix index covers cross-namespace cases: `stdlib.String.clone` ends
    // with `.String.clone`, so a `String.clone` probe lands on the stdlib
    // function automatically. Single match wins; ambiguity falls back to the
    // enclosing-namespace guess below.
    var suffixMatches = module.FindFunctionsByQualifiedSuffix(bareCandidate);
    if (suffixMatches.Count == 1) return suffixMatches[0].Name;
    if (suffixMatches.Count > 1) {
      var baseNames = suffixMatches.Select(f => UnmangleName(f.Name)).Distinct().ToList();
      if (baseNames.Count == 1) return baseNames[0];
    }
    // Type-alias fallback: BoxedString.clone -> stdlib.String.clone.
    if (_typeAliasSources.TryGetValue(typeName, out var aliasSource)) {
      var aliasedBare = $"{aliasSource}.{methodName}";
      if (module.FindFunctionByExactName(aliasedBare) != null) return aliasedBare;
      var aliasSuffix = module.FindFunctionsByQualifiedSuffix(aliasedBare);
      if (aliasSuffix.Count == 1) return aliasSuffix[0].Name;
    }
    // Nothing matched. Return the enclosing-namespace guess so downstream
    // error messages name the intended callee instead of a stripped variant.
    return string.IsNullOrEmpty(currentNamespace) ? bareCandidate : $"{currentNamespace}.{typeName}.{methodName}";
  }

  /// True if `structType` is the `Promise` type from stdlib/Builtins.maxon
  /// or any concrete alias of `Promise with T` / `Promise with (T, E)`.
  /// Both the generic source (`Promise`) and concrete instantiations
  /// (e.g. `Promise<Integer>`, `IntPromise`) are accepted.
  private bool IsPromiseStructType(IrStructType structType) {
    if (structType.Name == PromiseType.TypeName) return true;
    return _typeAliasSources.TryGetValue(structType.Name, out var source) && source == PromiseType.TypeName;
  }

  /// The error type a `Promise with (T, E)` storage type names, or null for a `Promise with T`,
  /// which names no error and therefore stores only NON-throwing promises.
  private static IrType? PromiseStorageErrorType(IrStructType promiseStructType) =>
      promiseStructType.TypeParams.TryGetValue(PromiseType.ErrorParam, out var errorType) ? errorType : null;

  /// True if a MaxonPromise value's inner kind/struct matches the `Element`
  /// type parameter of the given `Promise with T` (or alias) struct type.
  /// Used at call sites and assignments to validate that a promise produced
  /// by `async f()` can be stored where `Promise<T>` is expected.
  private bool PromiseElementMatches(IrStructType promiseStructType, MaxonPromise argPromise) {
    if (!promiseStructType.TypeParams.TryGetValue(PromiseType.ElementParam, out var elementType))
      return true; // Unresolved Element (bare `Promise`) — accept and defer.
    return PromiseInnerTypeMatchesElement(argPromise, elementType);
  }

  /// Emit a `Promise{inner: <handle>}` struct literal that wraps a raw MaxonPromise into the
  /// user-facing Promise struct type. Used when a promise produced by `async f()` flows into
  /// storage that expects a Promise struct (array elements, struct fields, named
  /// `let p PromiseAlias = ...` bindings).
  ///
  /// The handle is the WHOLE box. Everything else a `try await` needs to know — whether the
  /// thunk throws, what it throws, whether that error owns a heap payload — is read off the
  /// storage TYPE at the await site, not carried alongside the handle. Two bits used to ride
  /// along here (`throws_`, `errorIsHeapPtr`) precisely because the type could not say; now it
  /// can, so the storage type must AGREE with the promise, which is what this checks.
  ///
  /// The MaxonStructLiteralOp's field-init expects a MaxonValue. The raw i64 handle already
  /// lives in `promise` (same SSA id as the underlying async call result), so we reference it
  /// directly via MaxonInteger rather than emitting a fresh literal.
  private MaxonStruct BoxPromiseIntoStruct(MaxonPromise promise, IrStructType promiseStructType,
      Token errorToken) {
    CheckPromiseStorageErrorTypeMatches(promise, promiseStructType, errorToken);

    var fields = new List<(string, MaxonValue)> {
      (PromiseType.InnerField, new MaxonInteger(promise.Id))
    };
    var structLit = new MaxonStructLiteralOp(promiseStructType.Name, fields);
    _currentBlock!.AddOp(structLit);
    return (MaxonStruct)structLit.Result;
  }

  /// E3098: the storage type must name the same error the promise's thunk throws.
  ///
  /// Storing a throwing promise in a `Promise with T` is what used to ERASE the error type, and
  /// every downstream symptom followed from it being allowed: the `(e)` binding had no type and
  /// fell back to `int`, an associated-value payload had no static type to decref and leaked,
  /// and `try await` had nothing to check the enclosing function's `throws` against. Refusing
  /// the store is what makes those unrepresentable — and unlike the diagnostic this replaces,
  /// it can name the type that DOES work, because there now is one.
  private static void CheckPromiseStorageErrorTypeMatches(MaxonPromise promise, IrStructType promiseStructType,
      Token errorToken) {
    var storageErrorType = PromiseStorageErrorType(promiseStructType);
    var thunkErrorType = promise.ErrorType;

    // A bare generic `Promise` (Element unbound) is a deferred generic context — accept.
    if (!promiseStructType.TypeParams.ContainsKey(PromiseType.ElementParam)) return;
    if (storageErrorType is IrTypeParameterType) return;

    if (thunkErrorType == null && storageErrorType != null)
      throw new CompileError(ErrorCode.SemanticPromiseErrorTypeMismatch,
        $"'{promiseStructType.Name}' names the error type '{IrType.FormatAsSourceName(storageErrorType)}', but this promise's function does not throw — store it in a 'Promise with T' instead",
        errorToken.Line, errorToken.Column);

    if (thunkErrorType != null && storageErrorType == null)
      throw new CompileError(ErrorCode.SemanticPromiseErrorTypeMismatch,
        $"cannot store a promise from a function that throws '{thunkErrorType.Name}' in '{promiseStructType.Name}': it names the result type only, which would erase the error type — declare the storage as 'Promise with (T, {thunkErrorType.Name})' so 'try await' can bind and release the error",
        errorToken.Line, errorToken.Column);

    if (thunkErrorType != null && storageErrorType != null
        && thunkErrorType.Name != storageErrorType.Name)
      throw new CompileError(ErrorCode.SemanticPromiseErrorTypeMismatch,
        $"'{promiseStructType.Name}' names the error type '{IrType.FormatAsSourceName(storageErrorType)}', but this promise's function throws '{thunkErrorType.Name}'",
        errorToken.Line, errorToken.Column);
  }

  /// Element/inner-kind compatibility for the Promise type check above.
  /// Promotes the simple cases (struct/enum by name, primitive by kind) and
  /// rejects anything else as a mismatch so the caller can issue a clean
  /// diagnostic.
  private bool PromiseInnerTypeMatchesElement(MaxonPromise argPromise, IrType elementType) {
    if (elementType is IrTypeParameterType) return true; // generic context — accept
    if (elementType is IrStructType est)
      return argPromise.InnerStructTypeName != null
        && (argPromise.InnerStructTypeName == est.Name
            || IsStructTypeCompatible(argPromise.InnerStructTypeName, est.Name));
    if (elementType is IrEnumType eet)
      return argPromise.InnerStructTypeName == eet.Name;
    var elementKind = elementType.ToValueKind();
    return argPromise.InnerKind == elementKind;
  }

  /// Records method names from a conditional extension block that was skipped for a type
  /// because its where-constraints weren't satisfied.
  private void RecordSkippedConditionalExtensions(
      string typeName, IrStructType structType,
      List<int> functionPositions, Dictionary<string, List<string>> whereConstraints) {
    // Find the first unsatisfied constraint to use in the error message
    foreach (var (paramName, requiredInterfaces) in whereConstraints) {
      if (!structType.TypeParams.TryGetValue(paramName, out var concreteType)) continue;
      if (concreteType is IrTypeParameterType) continue;
      var concreteTypeName = IrType.FormatAsSourceName(concreteType);
      foreach (var iface in requiredInterfaces) {
        if (TypeConformsToInterface(concreteTypeName, iface)) continue;
        // Record each method name from this extension block
        foreach (var pos in functionPositions) {
          if (pos + 1 < _tokens.Count) {
            var methodName = _tokens[pos + 1].Value;
            _skippedConditionalExtensions[$"{typeName}.{methodName}"] =
              (paramName, iface, concreteTypeName);
          }
        }
        return;
      }
    }
  }

  /// Checks if a method was skipped as a conditional extension whose where-constraints aren't satisfied.
  /// Returns a descriptive error message suffix, or null if no such extension exists.
  private string? FindUnsatisfiedConditionalExtension(string typeName, string methodName) {
    if (_skippedConditionalExtensions.TryGetValue(
        $"{typeName}.{methodName}", out var info))
      return $" ('{methodName}' is available as a conditional extension where {info.ParamName} is {info.RequiredInterface}, but '{info.ConcreteTypeName}' does not implement '{info.RequiredInterface}')";
    return null;
  }

  /// Check if a type name is an associated type of the current struct being parsed.
  private bool IsAssociatedTypeName(string typeName) {
    return _typeRegistry.TryGetValue(typeName, out var type) && type is IrTypeParameterType;
  }

  /// Find an interface method by name across all registered interfaces.
  /// Searches for an interface method, restricted to interfaces the type parameter is constrained to.
  private IrInterfaceMethodSignature? FindInterfaceMethod(string methodName, string typeParamName) {
    // Only search interfaces that the type parameter is constrained to via where clauses
    if (_currentTypeName != null
        && _typeRegistry.TryGetValue(_currentTypeName, out var currentType)
        && currentType is IrStructType currentStruct
        && currentStruct.WhereConstraints.TryGetValue(typeParamName, out var constrainedInterfaces)) {
      foreach (var ifaceName in constrainedInterfaces) {
        if (_typeRegistry.TryGetValue(ifaceName, out var ifaceType) && ifaceType is IrInterfaceType iface) {
          var method = iface.Methods.FirstOrDefault(m => m.Name == methodName);
          if (method != null) return method;
        }
      }
    }
    return null;
  }

  private record LoopContext(string SourceLabel, string HeaderLabel, string ExitLabel, HashSet<string> ScopeVars,
    string? IterVarName = null, string? AdvanceMethodName = null, MaxonValueKind? ElementKind = null, string? ElementStructTypeName = null, string? IterableTypeName = null,
    string? RangeCounterVarName = null, MaxonValueKind? RangeElementKind = null, string? RangeStructTypeName = null,
    string? ForInResultVarName = null, string? IterableSourceTypeName = null,
    List<string>? HeaderScopeVars = null);
  private record MatchContext(string SourceLabel, string MergeLabel, HashSet<string> ScopeVars);

